@app.get("/api/demo")
def demo():
    profile = store.collection("profiles").document("demo").get()
    with engine.connect() as conn:
        rows = conn.execute(text("SELECT id, name FROM dbo.Items"))
        items = [dict(r._mapping) for r in rows]
    return jsonify(profile=profile.to_dict(), items=items)
